mapper.select:
SELECT m.business_id AS id, m.conversation_id, c.session_id, m.status
FROM digital_team_project_message m JOIN digital_team_project_conversation c
ON c.business_id = m.conversation_id
WHERE m.tenant_id = #{tenantId} AND m.project_id = #{projectId}
AND m.conversation_id = #{conversationId}
AND m.client_message_id = #{clientMessageId} LIMIT 1

SELECT message_text FROM digital_team_project_message
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND conversation_id = #{conversationId}
ORDER BY created_at DESC LIMIT #{limit}

mapper.update:
UPDATE digital_team_project_message SET message_text = CONCAT(message_text,
'\nHuman clarification: ', #{answer})
WHERE business_id = #{messageId} AND tenant_id = #{tenantId}

mapper.select:
SELECT business_id AS id, user_id, message_text, attachment_refs, status, created_at
FROM digital_team_project_message WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND conversation_id = #{taskId} ORDER BY created_at
